import{_ as l,a0 as o,w as r,s as g,ao as p,I as n,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"GoAccess：一個實時的 Web 日誌分析器及交互式查看器 | LCTT x X-CMD","titleTemplate":false,"description":"GoAccess：一個實時的 Web 日誌分析器及交互式查看器 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GoAccess：一個實時的 Web 日誌分析器及交互式查看器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GoAccess：一個實時的 Web 日誌分析器及交互式查看器 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer","title":"GoAccess：一個實時的 Web 日誌分析器及交互式查看器","tag":"201906","desc":""},"relativePath":"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer.md","filePath":"[post].md"}'),c={name:"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer.md"};function d(h,s,k,u,b,m){const a=o("Link");return r(),g("div",null,[s[32]||(s[32]=p('<h1 id="goaccess-一個實時的-web-日誌分析器及交互式查看器" tabindex="-1">GoAccess：一個實時的 Web 日誌分析器及交互式查看器 <a class="header-anchor" href="#goaccess-一個實時的-web-日誌分析器及交互式查看器" aria-label="Permalink to “GoAccess：一個實時的 Web 日誌分析器及交互式查看器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/12/222616h80pl0k0tt811071.jpg" alt=""></p><p>分析日誌文件對於 Linux 管理員來説是一件非常令人頭疼的事情，因為它記錄了很多東西。大多數新手和初級管理員都不知道如何分析。如果你在分析日誌方面擁有很多知識，那麼你就成了 *NIX 系統高手。</p><p>Linux 中有許多工具可以輕鬆分析日誌。GoAccess 是允許用户輕鬆分析 Web 服務器日誌的工具之一。我們將在本文中詳細討論 GoAccess 工具。</p><h3 id="goaccess" tabindex="-1">GoAccess <a class="header-anchor" href="#goaccess" aria-label="Permalink to “GoAccess”">​</a></h3><p>GoAccess 是一個實時 Web 日誌分析器和交互式查看器，可以在 *nix 系統中的終端運行或通過瀏覽器訪問。</p><p>GoAccess 需要的依賴極少，它是用 C 語言編寫的，只需要 ncurses。</p><p>它支持 Apache、Nginx 和 Lighttpd 日誌。它為需要動態可視化服務器報告的系統管理員即時提供了快速且有價值的 HTTP 統計信息。</p><p>GoAccess 可以解析指定的 Web 日誌文件並將數據輸出到 X 終端和瀏覽器。</p><p>GoAccess 被設計成一個基於終端的快速日誌分析器。其核心思想是實時快速分析和查看 Web 服務器統計信息，而無需使用瀏覽器。</p><p>默認輸出是在終端輸出，它也能夠生成完整的、自包含的實時 HTML 報告，以及 JSON 和 CSV 報告。</p><p>GoAccess 支持任何自定義日誌格式，並包含以下預定義日誌格式選項：Apache/Nginx 中的組合日誌格式 XLF/ELF，Apache 中的通用日誌格式 CLF，但不限於此。</p><h3 id="goaccess-功能" tabindex="-1">GoAccess 功能 <a class="header-anchor" href="#goaccess-功能" aria-label="Permalink to “GoAccess 功能”">​</a></h3><ul><li>完全實時：所有指標在終端上每 200 毫秒更新一次，在 HTML 輸出上每秒更新一次。</li><li>跟蹤應用程序響應時間：跟蹤服務請求所需的時間。如果你想跟蹤減慢了網站速度的網頁，則非常有用。</li><li>訪問者：按小時或日期確定最慢運行的請求的點擊量、訪問者數、帶寬數和指標。</li><li>按虛擬主機的度量標準：如果有多個虛擬主機（<code>Server</code>），它提供了一個面板，可顯示哪些虛擬主機正在消耗大部分 Web 服務器資源。</li></ul><h3 id="如何安裝-goaccess" tabindex="-1">如何安裝 GoAccess？ <a class="header-anchor" href="#如何安裝-goaccess" aria-label="Permalink to “如何安裝 GoAccess？”">​</a></h3><p>我建議用户在包管理器的幫助下從發行版官方的存儲庫安裝 GoAccess。它在大多數發行版官方存儲庫中都可用。</p><p>我們知道，我們在標準發行方式的發行版中得到的是過時的軟件包，而滾動發行方式的發行版總是包含最新的軟件包。</p><p>如果你使用標準發行方式的發行版運行操作系統，我建議你檢查替代選項，如 PPA 或 GoAccess 官方維護者存儲庫等，以獲取最新的軟件包。</p>',18)),n("p",null,[s[2]||(s[2]=e("對於 Debian / Ubuntu 系統，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-get-apt-cache-command-examples-manage-packages-debian-ubuntu-systems/"},{default:t(()=>[...s[0]||(s[0]=[e("APT-GET 命令",-1)])]),_:1}),s[3]||(s[3]=e("或 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-command-examples-manage-packages-debian-ubuntu-systems/"},{default:t(()=>[...s[1]||(s[1]=[e("APT 命令",-1)])]),_:1}),s[4]||(s[4]=e("在你的系統上安裝 GoAccess。",-1))]),s[33]||(s[33]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install goaccess</span></span></code></pre></div><p>要獲取最新的 GoAccess 包，請使用以下 GoAccess 官方存儲庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;deb https://deb.goaccess.io/ $(lsb_release -cs) main&quot; | sudo tee -a /etc/apt/sources.list.d/goaccess.list</span></span>
<span class="line"><span>$ wget -O - https://deb.goaccess.io/gnugpg.key | sudo apt-key add -</span></span>
<span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install goaccess</span></span></code></pre></div>`,3)),n("p",null,[s[6]||(s[6]=e("對於 RHEL / CentOS 系統，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:t(()=>[...s[5]||(s[5]=[e("YUM 包管理器",-1)])]),_:1}),s[7]||(s[7]=e("在你的系統上安裝 GoAccess。",-1))]),s[34]||(s[34]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install goaccess</span></span></code></pre></div>',1)),n("p",null,[s[9]||(s[9]=e("對於 Fedora 系統，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/dnf-command-examples-manage-packages-fedora-system/"},{default:t(()=>[...s[8]||(s[8]=[e("DNF 包管理器",-1)])]),_:1}),s[10]||(s[10]=e("在你的系統上安裝 GoAccess。",-1))]),s[35]||(s[35]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install goaccess</span></span></code></pre></div>',1)),n("p",null,[s[12]||(s[12]=e("對於基於 ArchLinux / Manjaro 的系統，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/pacman-command-examples-manage-packages-arch-linux-system/"},{default:t(()=>[...s[11]||(s[11]=[e("Pacman 包管理器",-1)])]),_:1}),s[13]||(s[13]=e("在你的系統上安裝 GoAccess。",-1))]),s[36]||(s[36]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S goaccess</span></span></code></pre></div>',1)),n("p",null,[s[15]||(s[15]=e("對於 openSUSE Leap 系統，使用",-1)),i(a,{href:"https://www.2daygeek.com/zypper-command-examples-manage-packages-opensuse-system/"},{default:t(()=>[...s[14]||(s[14]=[e("Zypper 包管理器",-1)])]),_:1}),s[16]||(s[16]=e("在你的系統上安裝 GoAccess。",-1))]),s[37]||(s[37]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zypper install goaccess</span></span>
<span class="line"><span># zypper ar -f obs://server:http</span></span>
<span class="line"><span># zypper ref &amp;&amp; zypper in goaccess</span></span></code></pre></div><h3 id="如何使用-goaccess" tabindex="-1">如何使用 GoAccess？ <a class="header-anchor" href="#如何使用-goaccess" aria-label="Permalink to “如何使用 GoAccess？”">​</a></h3><p>成功安裝 GoAccess 後。只需輸入 <code>goaccess</code> 命令，然後輸入 Web 服務器日誌位置即可查看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess [options] /path/to/Web Server/access.log</span></span>
<span class="line"><span># goaccess /var/log/apache/2daygeek_access.log</span></span></code></pre></div><p>執行上述命令時，它會要求您選擇日誌格式配置。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-1.png" alt=""></p><p>我用 Apache 訪問日誌對此進行了測試。Apache 日誌被分為十五個部分。詳情如下。主要部分顯示了這十五個部分的摘要。</p><p>以下屏幕截圖包括四個部分，例如唯一身份訪問者、請求的文件、靜態請求、未找到的網址。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-3.png" alt=""></p><p>以下屏幕截圖包括四個部分，例如訪客主機名和 IP、操作系統、瀏覽器、時間分佈。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-3.png" alt=""></p><p>以下屏幕截圖包括四個部分，例如來源網址、來源網站，Google 的搜索引擎結果、HTTP狀態代碼。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-4.png" alt=""></p><p>如果要生成 html 報告，請使用以下命令。最初我在嘗試生成 html 報告時遇到錯誤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess 2daygeek_access.log -a &gt; report.html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GoAccess - version 1.3 - Nov 23 2018 11:28:19</span></span>
<span class="line"><span>Config file: No config file used</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fatal error has occurred</span></span>
<span class="line"><span>Error occurred at: src/parser.c - parse_log - 2764</span></span>
<span class="line"><span>No time format was found on your conf file.Parsing... [0] [0/s]</span></span></code></pre></div><p>它説“你的 conf 文件沒有找到時間格式”。要解決此問題，請為其添加 “COMBINED” 日誌格式選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess -f 2daygeek_access.log --log-format=COMBINED -o 2daygeek.html</span></span>
<span class="line"><span>Parsing...[0,165] [50,165/s]</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-5.png" alt=""></p><p>GoAccess 也允許你訪問和分析實時日誌並進行過濾和解析。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/apache/2daygeek_access.log | goaccess -</span></span></code></pre></div><p>更多細節請參考其 man 手冊頁或幫助。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># man goaccess</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># goaccess --help</span></span></code></pre></div><hr>`,23)),n("p",null,[s[18]||(s[18]=e("via: ",-1)),i(a,{href:"https://www.2daygeek.com/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer/"},{default:t(()=>[...s[17]||(s[17]=[e("https://www.2daygeek.com/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer/",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("作者：",-1)),i(a,{href:"https://www.2daygeek.com/author/vinoth/"},{default:t(()=>[...s[19]||(s[19]=[e("Vinoth Kumar",-1)])]),_:1}),s[24]||(s[24]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[20]||(s[20]=[e("lujun9972",-1)])]),_:1}),s[25]||(s[25]=e(" 譯者：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[e("wxy",-1)])]),_:1}),s[26]||(s[26]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[22]||(s[22]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[29]||(s[29]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[27]||(s[27]=[e("LCTT",-1)])]),_:1}),s[30]||(s[30]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[28]||(s[28]=[e("Linux中國",-1)])]),_:1}),s[31]||(s[31]=e(" 榮譽推出",-1))])])}const w=l(c,[["render",d]]);export{A as __pageData,w as default};
